rule.definition:
a!localVariables(
  local!page: if(a!isNotNullOrEmpty(ri!page), ri!page, 1),
  local!recordsPerPage: if(
    a!isNotNullOrEmpty(ri!limit),
    ri!limit,
    - 1
  ),
  local!data: a!refreshVariable(
    value: if(
      or(
        a!isNullOrEmpty(ri!process),
        a!isNullOrEmpty(ri!subProcessID),
        a!isNullOrEmpty(ri!processID)
      ),
      {},
      a!queryProcessAnalytics(
        report: #"_a-0000eccb-293d-8000-9ba8-011c48011c48_106651",
        query: #"SYSTEM_SYSRULES_query"(
          logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
            operator: "AND",
            filters: {
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c0",
                operator: "=",
                value: ri!process
              ),
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c5",
                operator: "=",
                value: ri!subProcessID
              ),
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c7",
                operator: "=",
                value: ri!processID
              ),
              /*a!queryFilter(field: "c13", operator: "=", value: 1),*/
              #"SYSTEM_SYSRULES_queryFilter"(field: "c1", operator: "=", value: 2)
            },
            ignoreFiltersWithEmptyValues: "false"
          ),
          pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
            startIndex: (local!page - 1) * local!recordsPerPage + 1,
            batchSize: local!recordsPerPage
          )
        )
      ).data,

    ),
    refreshOnVarChange: ri!intentos,

  ),
  local!dataLength: a!refreshVariable(
    value: if(
      or(
        a!isNullOrEmpty(ri!process),
        a!isNullOrEmpty(ri!subProcessID),
        a!isNullOrEmpty(ri!processID)
      ),
      {},
      a!queryProcessAnalytics(
        report: #"_a-0000eccb-293d-8000-9ba8-011c48011c48_106651",
        query: #"SYSTEM_SYSRULES_query"(
          logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
            operator: "AND",
            filters: {
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c0",
                operator: "=",
                value: ri!process
              ),
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c5",
                operator: "=",
                value: ri!subProcessID
              ),
              #"SYSTEM_SYSRULES_queryFilter"(
                field: "c7",
                operator: "=",
                value: ri!processID
              ),
              #"SYSTEM_SYSRULES_queryFilter"(field: "c1", operator: "=", value: 2),
              /*a!queryFilter(field: "c13", operator: "=", value: 1)*/
            },
            ignoreFiltersWithEmptyValues: "false"
          ),
          pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: - 1)
        )
      ).data,

    ),
    refreshOnVarChange: ri!intentos,

  ),
  {
    length: count(local!dataLength),
    data: local!data,
    intentos: ri!intentos
  }
)
